sys_script_email.script:
if (current.u_item_type == 'cmdb_ci_computer') {
        var url = 'https://nowlearning-nlinst04834837-7sjwp-0001.lab.service-now.com/api/now/table/';
        var table = 'u_password_vault';
        var query = 'u_asset=' + current.cmdb_ci.asset_tag;
        var field = 'u_password';
        var request = new sn_ws.RESTMessageV2();

        request.setEndpoint(
            url + table +
            '?sysparm_query=' + query +
            '&sysparm_fields=' + field +
            '&sysparm_limit=1'
        );
        request.setHttpMethod('GET');
        request.setBasicAuth('admin', '324DLMGMHZ5h');
        request.setRequestHeader("Accept","application/json");
        var response = request.execute();
        var body = JSON.parse(response.getBody());
        var password = body.result[0].u_password;
        template.print('Laptop password: ' + password);
    }
